select jsonb_build_object(
'columns',(select jsonb_agg(to_jsonb(c)) from information_schema.columns c where table_schema='public' and table_name=any(array['attempts','rc_attempts','rc_drill_sessions','bootcamp_kv','guided_drill_assignments','activity_assignments','activity_item_responses','homework_assignments','practice_test_runs','classroom_items','section_history'])),
'policies',(select jsonb_agg(to_jsonb(p)) from pg_policies p where schemaname='public' and tablename=any(array['attempts','rc_attempts','rc_drill_sessions','bootcamp_kv','guided_drill_assignments','activity_assignments','activity_item_responses','homework_assignments','practice_test_runs','classroom_items','section_history'])),
'constraints',(select jsonb_agg(jsonb_build_object('table',r.relname,'name',c.conname,'definition',pg_get_constraintdef(c.oid))) from pg_constraint c join pg_class r on r.oid=c.conrelid join pg_namespace n on n.oid=r.relnamespace where n.nspname='public' and r.relname=any(array['attempts','rc_attempts','rc_drill_sessions','bootcamp_kv','guided_drill_assignments','activity_assignments','activity_item_responses','homework_assignments','practice_test_runs','classroom_items','section_history'])),
'indexes',(select jsonb_agg(to_jsonb(i)) from pg_indexes i where schemaname='public' and tablename=any(array['attempts','rc_attempts','rc_drill_sessions','bootcamp_kv','guided_drill_assignments','activity_assignments','activity_item_responses','homework_assignments','practice_test_runs','classroom_items','section_history'])),
'triggers',(select jsonb_agg(jsonb_build_object('table',r.relname,'definition',pg_get_triggerdef(t.oid),'function',pg_get_functiondef(t.tgfoid))) from pg_trigger t join pg_class r on r.oid=t.tgrelid join pg_namespace n on n.oid=r.relnamespace where not t.tgisinternal and n.nspname='public' and r.relname=any(array['attempts','rc_attempts','rc_drill_sessions','bootcamp_kv','guided_drill_assignments','activity_assignments','activity_item_responses','homework_assignments','practice_test_runs','classroom_items','section_history']))
) as metadata;
